const searchCardTitles = `-- name: SearchCardTitles :many
SELECT id, list_id, board_id, title, description, position, due_at, due_done, start_at, cover_attachment_id, is_template, recurrence_id, archived_at, due_soon_notified_at, overdue_notified_at, created_by, created_at, updated_at, version FROM cards WHERE board_id IN (/*SLICE:board_ids*/?) AND is_template = FALSE AND archived_at IS NULL
  AND title LIKE '%' || CAST(?2 AS TEXT) || '%' ORDER BY updated_at DESC LIMIT ?3
`

type SearchCardTitlesParams struct {
	BoardIds []string
	Query    string
	Limit    int64
}

func (q *Queries) SearchCardTitles(ctx context.Context, arg SearchCardTitlesParams) ([]Card, error) {
	query := searchCardTitles
	var queryParams []interface{}
	if len(arg.BoardIds) > 0 {
		for _, v := range arg.BoardIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:board_ids*/?", strings.Repeat(",?", len(arg.BoardIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:board_ids*/?", "NULL", 1)
	}
	queryParams = append(queryParams, arg.Query)
	queryParams = append(queryParams, arg.Limit)
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Card
	for rows.Next() {
		var i Card
		if err := rows.Scan(
			&i.ID,
			&i.ListID,
			&i.BoardID,
			&i.Title,
			&i.Description,
			&i.Position,
			&i.DueAt,
			&i.DueDone,
			&i.StartAt,
			&i.CoverAttachmentID,
			&i.IsTemplate,
			&i.RecurrenceID,
			&i.ArchivedAt,
			&i.DueSoonNotifiedAt,
			&i.OverdueNotifiedAt,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

